// Demo: Signature Cartographer - Domain Model Generator framework pillar
(function(){'use strict';
var DATA={"label": "Signature Cartographer - Domain Model Generator framework pi", "edges": [["Cartographer", "Domain"], ["Domain", "Model"], ["Cartographer", "Model"], ["Model", "Generator"]]};

var adj={};DATA.edges.forEach(function(e){(adj[e[0]]=adj[e[0]]||[]).push(e[1]);});
var state={},stack=[],cycle=null;
function dfs(n){state[n]=1;stack.push(n);
  var nb=adj[n]||[];
  for(var i=0;i<nb.length;i++){var m=nb[i];
    if(state[m]===1){cycle=stack.slice(stack.indexOf(m)).concat(m);return true;}
    if(!state[m]&&dfs(m))return true;}
  stack.pop();state[n]=2;return false;}
console.log('Cycle check ('+DATA.label+'):');
var nodes={};DATA.edges.forEach(function(e){nodes[e[0]]=1;nodes[e[1]]=1;});
Object.keys(nodes).forEach(function(n){if(!state[n])dfs(n);});
if(cycle)console.log('CYCLE: '+cycle.join(' -> '));
else console.log('ACYCLIC - safe to build in dependency order');
})();

